import React from 'react';

import A4Page from '@components/A4Page';
import PageLoader from '@components/PageLoader/index';
import Breadcrumb from '@ui-kit/Breadcrumb/index';
import PohCheckbox from '@ui-kit/Checkbox';
import PohContainer from '@ui-kit/layout/Container';

import Sticker from './components/Sticker';
import StickerGroup from './components/StickerGroup/index';
import { IProductForPrint } from './mapper';
import { getHikingDataAsync } from '../../../@services/hiking.service';
import { getHikingDuty } from '../../../@services/hikingDuty.service';
import { getHikingProductsForPrint } from '../../../@services/hikingMenu.service';
import { IHikingDuty } from '../../../@types/hiking.baseTypes';
import { IHiker, IHikingData } from '../../../@types/hiking.types';

export const filterHikersByDate =
  (d1: Date, d2: Date | null = null) =>
  (h: IHiker) => {
    let byStartDate = true;
    let byFinishDate = true;
    if (h.dateFrom) {
      byStartDate = h.dateFrom <= d1;
    }

    if (h.dateTo) {
      byFinishDate = h.dateTo >= (d2 || d1);
    }

    return byStartDate && byFinishDate;
  };

interface IHikingMenuPrintStickersProps {
  id_hiking: number;
}

const HikingMenuPrintStickers: React.FC<IHikingMenuPrintStickersProps> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [stickers, setStickers] = React.useState<IProductForPrint[]>([]);
  const [duty, setDuty] = React.useState<IHikingDuty[]>([]);

  const [withDay, setWithDay] = React.useState(false);
  const [withDuty, setWithDuty] = React.useState(false);
  const [useGroup, seUseGroup] = React.useState(false);
  const [withAva, setWithAva] = React.useState(true);

  React.useEffect(() => {
    getHikingDataAsync(id_hiking).then(setHikingData);
    getHikingProductsForPrint(id_hiking).then((x) => {
      setStickers(x.sort((a, b) => a.name.localeCompare(b.name)));
    });
  }, [id_hiking]);

  React.useEffect(() => {
    withDuty && getHikingDuty(id_hiking).then(setDuty);
  }, [withDuty]);

  const daysMap: Record<string, number> = React.useMemo(() => {
    if (!withDay || !hikingData) {
      return {};
    }
    let d = hikingData.start;
    let i = 1;
    const acc: Record<string, number> = {};

    while (d < hikingData.finish) {
      acc[d.toLocaleDateString()] = i;
      d = new Date(d.getTime() + 86400000);
      i++;
    }

    return acc;
  }, [hikingData, withDay]);

  const dutyMap: Record<string, IHikingDuty[]> = React.useMemo(() => {
    if (!withDuty) {
      return {};
    }
    return duty.reduce<Record<string, IHikingDuty[]>>((acc, val) => {
      const k = val.date.toLocaleDateString();
      if (!acc[k]) {
        acc[k] = [];
      }
      acc[k].push(val);
      return acc;
    }, {});
  }, [duty, withDuty]);

  if (hikingData == null || stickers == null) {
    return <PageLoader />;
  }

  return (
    <PohContainer className="px-1">
      <div className="d-print-none">
        <Breadcrumb
          data={[
            { href: '/hiking', text: 'Походы' },
            { href: `/hiking/${id_hiking}`, text: hikingData.name },
            { href: `/hiking/${id_hiking}/menu`, text: 'Меню похода' },
            { href: `/hiking/${id_hiking}/menu/stickers`, text: 'Наклейки', active: true },
          ]}
        />
        <h3 className="mb-3 d-print-none">Наклейки похода &laquo;{hikingData.name}&raquo;</h3>
        <aside className="d-flex d-print-none mt-n2 mb-3" style={{ gap: 24 }}>
          <PohCheckbox checked={useGroup} onChange={seUseGroup} label="Группировать назначенные" />
          <PohCheckbox checked={withAva} onChange={setWithAva} label="Фотки" />
          <PohCheckbox checked={withDuty} onChange={setWithDuty} label="Дежурные" />
          <PohCheckbox checked={withDay} onChange={setWithDay} label="Дни похода" />
        </aside>
      </div>
      <A4Page>
        {!useGroup && (
          <section style={{ columns: 5 }}>
            {stickers.map((st) => {
              const hikersForAct = hikingData.hikers.filter(filterHikersByDate(st.date));
              const k = st.date.toLocaleDateString();
              return (
                <Sticker
                  data={st}
                  key={`${st.date}${st.recipeName}${st.idProduct}`}
                  hikersCount={hikersForAct.length}
                  hikersMaxCount={hikingData.hikers.length}
                  withAva={withAva}
                  day={daysMap[k]}
                  duty={dutyMap[k]}
                />
              );
            })}
          </section>
        )}

        {useGroup && (
          <section className="d-flex flex-column justify-content-center">
            <h3 className="mt-4">Назначенные</h3>
            <div style={{ columns: 5 }}>
              {Object.values(
                stickers
                  .filter((x) => x.isForced)
                  .reduce<
                    Record<
                      number,
                      IProductForPrint & {
                        usages: Array<IProductForPrint & { hikersForAct: IHiker[] }>;
                        totalAmount: number;
                      }
                    >
                  >((acc, val) => {
                    const hikersForAct = hikingData.hikers.filter(filterHikersByDate(val.date));
                    if (!acc[val.idProduct]) {
                      acc[val.idProduct] = {
                        ...val,
                        usages: [],
                        totalAmount: 0,
                      };
                    }

                    acc[val.idProduct].usages.push({ ...val, hikersForAct });
                    acc[val.idProduct].totalAmount += val.amount * hikersForAct.length;
                    return acc;
                  }, {}),
              ).map((st) => (
                <StickerGroup
                  data={st}
                  key={`${st.date}${st.recipeName}${st.idProduct}`}
                  hikersMaxCount={hikingData.hikers.length}
                />
              ))}
            </div>

            <h3 className="mt-4">Прочие</h3>
            <div style={{ columns: 5 }}>
              {stickers
                .filter((x) => !x.isForced)
                .map((st) => {
                  const hikersForAct = hikingData.hikers.filter(filterHikersByDate(st.date));
                  const k = st.date.toLocaleDateString();

                  return (
                    <Sticker
                      data={st}
                      key={`${st.date}${st.recipeName}${st.idProduct}`}
                      hikersCount={hikersForAct.length}
                      hikersMaxCount={hikingData.hikers.length}
                      withAva={withAva}
                      day={daysMap[k]}
                      duty={dutyMap[k]}
                    />
                  );
                })}
            </div>
          </section>
        )}
      </A4Page>
    </PohContainer>
  );
};

export default HikingMenuPrintStickers;
