import clsx from 'clsx';

import { IHiker } from '@apps/Hiking/@types/hiking.types';
import { round } from '@helpers/mathHelper';

import style from './style.module.less';
import { IProductForPrint } from '../../mapper';

const StickerGroup = ({
  data,
  hikersMaxCount,
}: {
  data: IProductForPrint & {
    usages: Array<IProductForPrint & { hikersForAct: IHiker[] }>;
    totalAmount: number;
  };
  hikersMaxCount: number;
}) => (
  <div className={style.sticker}>
    <strong className={style.header}>
      <span className={clsx('float-end', style.weight)}>{round(data.totalAmount, 1)}</span>
      {data.name}
    </strong>
    <div className={style.assignee}>
      <small className="float-end">{data.usages.length}&thinsp;раз</small>
      <small>отв.: {data?.user?.name || '-'}</small>
    </div>
    <table className={clsx('table table-sm table-bordered w-100', style.table)}>
      <tbody>
        <tr>
          <td>Дата</td>
          <td>Время</td>
          <td>Блюдо</td>
          <td>г.</td>
        </tr>
        {data.usages.map((us) => (
          <tr key={us.date.toLocaleString() + us.actName}>
            <td>
              <small>{us.date.toLocaleDateString().substr(0, 5)}</small>
            </td>
            <td>
              <small>{us.date.toLocaleTimeString().substr(0, 5)}</small>
            </td>
            <td className={clsx(style.tdTruncate)}>{us.recipeName}</td>
            <td className="text-end">
              {hikersMaxCount !== us.hikersForAct.length ? (
                <>
                  <sup>{round(us.amount * us.hikersForAct.length)}</sup>/
                  <sub>{us.hikersForAct.length}</sub>={us.amount}
                </>
              ) : (
                round(us.amount * us.hikersForAct.length)
              )}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  </div>
);

export default StickerGroup;
