import React from 'react';

import People from '@pohodnik/icons/svg/People/People';
import clsx from 'clsx';

import { round } from '@helpers/mathHelper';
import PohAva from '@ui-kit/Ava';

import style from './style.module.less';
import { IHikingDuty } from '../../../../../@types/hiking.baseTypes';
import { getShortName } from '../../../HikingMenu/helper';
import { IProductForPrint } from '../../mapper';

interface IProductStickerProps {
  data: IProductForPrint;
  hikersCount: number;
  hikersMaxCount?: number;
  withAva?: boolean;
  day?: number;
  duty?: IHikingDuty[];
}

const Sticker: React.FC<IProductStickerProps> = ({
  data,
  hikersCount,
  hikersMaxCount = 0,
  withAva = false,
  day,
  duty,
}) => (
  <div className={style.sticker}>
    <strong className={style.header}>
      <span className={clsx('float-end', style.weight)}>{round(data.amount * hikersCount, 1)}</span>
      {data.name}
      {data.ex ? (
        <em>
          <small>
            <small className="text-danger"> ex.</small> {getShortName(data.ex.name)}{' '}
            <sup>&times;{data.ex.rate}</sup>
          </small>
        </em>
      ) : (
        ''
      )}
    </strong>

    <div className="overflow-hidden text-truncate">
      <em>
        <small className="overflow-hidden text-nowrap">{data.recipeName}</small>
      </em>
    </div>
    <small className="d-flex justify-content-between align-items-center" style={{ gap: 3 }}>
      <small className="overflow-hidden">
        {day ? (
          <strong className={clsx(style.dayAct)}>
            {day}
            {data.actName[0].toLowerCase()}
          </strong>
        ) : (
          data.actName
        )}
      </small>
      <small>{data.date.toLocaleDateString('default', { dateStyle: 'short' })}</small>
      <small>{data.date.toLocaleTimeString('default', { timeStyle: 'short' })}</small>

      <small className="ml-auto">
        {hikersMaxCount && hikersMaxCount !== hikersCount && (
          <small className="d-flex align-items-center text-info">
            <small>
              <People />
            </small>
            {hikersCount}
          </small>
        )}
      </small>
    </small>
    <div className={style.assignee} style={{ lineHeight: 0.9 }}>
      <small>отв.: {data?.user?.name || '-'}</small>
      {duty && (
        <small>
          &nbsp; &nbsp; &nbsp; деж.:{' '}
          {duty
            .map((d) => {
              return d.user.name
                .split(/\s/)
                .map((x) => x[0])
                .join('');
            })
            .join(', ')}
        </small>
      )}
    </div>

    <div className="d-flex align-items-end justify-content-between">
      <table className={clsx(style.table)}>
        <tbody>
          <tr>
            <th>Порц.</th>
            <th>Б</th>
            <th>Ж</th>
            <th>У</th>
            <th>Ккал</th>
          </tr>
          <tr>
            <td>
              {round(data.amount, 1)}&thinsp;<small>г</small>
            </td>
            <td>{round(data.proteins, 0)}</td>
            <td>{round(data.fats, 0)}</td>
            <td>{round(data.carbs, 0)}</td>
            <td>{round(data.energy, 0)}</td>
          </tr>
        </tbody>
      </table>

      {withAva && data?.user && (
        <PohAva
          src={data?.user?.photo}
          alt={data?.user?.name}
          className={clsx(style.ava, 'float-end')}
          width={24}
        />
      )}
    </div>
  </div>
);

export default Sticker;
